cy.request({
  method: 'GET',
  url: `${baseUrl}/usuarios/admin`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  },
  qs: {
    pagina: 1,
    tamano: 50
  }
}).then(response => {
  expect(response.status).to.equal(200);
  expect(response.body).to.have.property('items');
  expect(response.body.items).to.be.an('array');
  expect(response.body.items.length).to.be.greaterThan(0);
  cy.log(`Total de usuarios encontrados: ${response.body.items.length}`);
});

expect(idUsuarioPrueba).to.exist;
expect(idUsuarioPrueba).to.be.a('number');
expect(idUsuarioPrueba).to.be.greaterThan(0);
cy.log(`Usuario de prueba identificado con ID: ${idUsuarioPrueba}`);

cy.request({
  method: 'GET',
  url: `${baseUrl}/usuarios/${idUsuarioPrueba}/detalle`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  }
}).then(response => {
  expect(response.status).to.equal(200);
  expect(response.body).to.have.property('id_usuario');
  expect(response.body).to.have.property('correo_electronico');
  expect(response.body).to.have.property('estado_cuenta');
  expect(response.body.id_usuario).to.equal(idUsuarioPrueba);
  expect(response.body.correo_electronico).to.equal('juan.carlos@email.com');
  // Guardar estado original para fines de restauración
  estadoOriginal = response.body.estado_cuenta;
  cy.log(`Usuario encontrado: ${response.body.correo_electronico}`);
  cy.log(`Estado original: ${estadoOriginal}`);
});

cy.request({
  method: 'POST',
  url: `${baseUrl}/usuarios/${idUsuarioPrueba}/gestionar`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  },
  body: {
    accion_cuenta: 'bloquear'
  },
  failOnStatusCode: false
}).then(response => {
  cy.log(`Respuesta bloqueo: ${JSON.stringify(response.body)}`);
  expect(response.status).to.equal(200);
});

cy.request({
  method: 'GET',
  url: `${baseUrl}/usuarios/${idUsuarioPrueba}/detalle`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  }
}).then(response => {
  expect(response.status).to.equal(200);
  expect(response.body).to.have.property('estado_cuenta');
  const estadoActual = response.body.estado_cuenta.toLowerCase();
  cy.log(`Estado después del bloqueo: ${response.body.estado_cuenta}`);
  expect(estadoActual).to.include('bloque');
});

cy.request({
  method: 'POST',
  url: `${baseUrl}/usuarios/${idUsuarioPrueba}/gestionar`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  },
  body: {
    accion_cuenta: 'activar'
  },
  failOnStatusCode: false
}).then(response => {
  cy.log(`Respuesta restauración: ${JSON.stringify(response.body)}`);
  expect(response.status).to.equal(200);
});

cy.request({
  method: 'GET',
  url: `${baseUrl}/usuarios/${idUsuarioPrueba}/detalle`,
  headers: {
    Authorization: `Bearer ${tokenAdmin}`
  }
}).then(response => {
  expect(response.status).to.equal(200);
  expect(response.body).to.have.property('estado_cuenta');
  const estadoFinal = response.body.estado_cuenta.toLowerCase();
  cy.log(`Estado final de la cuenta: ${response.body.estado_cuenta}`);
  expect(estadoFinal).to.include('activo');
});
